import 'dart:convert';
import 'package:flutter/widgets.dart';

/// Guess Number game screen image embedded directly in this Dart file.
/// No separate PNG asset or pubspec.yaml entry is required.
class GuessNumberGameImage extends StatelessWidget {
  const GuessNumberGameImage({super.key});

  static const String _imageBase64 = '';

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_imageBase64),
      fit: BoxFit.contain,
      width: double.infinity,
    );
  }
}
